from httpbin.core import app
client = app.test_client()

def test_get_with_query_params_reflected_in_args():
    r = client.get('/get?foo=bar&baz=qux')
    assert r.status_code == 200
    data = r.get_json()
    assert data['args'] == {'foo': 'bar', 'baz': 'qux'}
    assert 'foo=bar' in data['url']
    assert 'baz=qux' in data['url']

def test_get_with_single_query_param():
    r = client.get('/get?key=value')
    assert r.status_code == 200
    data = r.get_json()
    assert data['args'] == {'key': 'value'}

def test_get_with_no_query_params_args_is_empty_dict():
    r = client.get('/get')
    assert r.status_code == 200
    data = r.get_json()
    assert data['args'] == {}
    assert data['args'] != {'unexpected': 'value'}

from httpbin.core import app
client = app.test_client()

def test_get_response_keys_exact_set_no_extra_keys():
    r = client.get('/get')
    assert r.status_code == 200
    data = r.get_json()
    expected_keys = {'url', 'args', 'headers', 'origin'}
    forbidden_keys = {'form', 'data', 'files', 'json', 'method'}
    assert set(data.keys()) == expected_keys
    assert len(data.keys()) == 4
    for key in forbidden_keys:
        assert key not in data, f"Unexpected key '{key}' found in response"
